/* A scene renderer: artwork, terrain and framing are functions of time + activity. */
(() => {
 const canvas=document.querySelector('#journey-canvas'),stage=document.querySelector('.journey-stage'),section=document.querySelector('.journey');
 if(!canvas)return;const c=canvas.getContext('2d'),bg=document.querySelector('#places-canvas'),bc=bg.getContext('2d');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let W=0,H=0,mode=0,t=0,last=0,paused=reduced.matches,visible=true,p=0,transition=1,previousMode=0,lastScrollScene=-1,manualMode=false,needsDraw=true;
 const sheets=['run-ironman','hike-ironman','bike-ironman','swim-ironman','snow-ironman'].map(name=>{const img=new Image();img.onload=()=>{needsDraw=true};img.src=`assets/${name}-sheet.webp`;return img});
 const worlds=[
 {title:'Complex problems.<br>Shipped.',description:'Principal mobile engineer. AI & agent builder.<br>11+ years turning difficult ideas into working products.',label:'01 / THE ENGINEER',role:'ENGINEER. ARCHITECT. PROBLEM SOLVER.',nav:[['Professional','#experience'],['Projects','#work'],['DIY lab','#workshop'],['Endurance','#miles']],cta:['Explore my engineering','#experience'],feature:['Baton — tools for the agent era','#baton']},
 {title:'If it doesn’t exist.<br>Build it.',description:'Independent products. Useful experiments.<br>The DIY mindset behind One Energy Together.',label:'02 / THE INDEPENDENT BUILDER',role:'CURIOUS MIND. HANDS-ON BUILDER.',nav:[['DIY lab','#workshop'],['Personal projects','#work'],['My story','#about'],['Field notes','#journal']],cta:['Step inside my workshop','#workshop'],feature:['CoreRun — download on the App Store','https://apps.apple.com/us/app/core-run/id6759610412']},
 {title:'The finish line?<br>A new beginning.',description:'Ironman. Ultra runner. A 202-mile ride.<br>A life measured in experiences, not just releases.',label:'03 / THE ENDURANCE ATHLETE',role:'SWIM. RIDE. RUN. REPEAT.',nav:[['Milestones','#miles'],['Endurance','#endurance'],['Field notes','#journal'],['Connect','#contact']],cta:['Follow the miles','#miles'],feature:['202 miles. Two cities. One story','https://studio.oneenergytogether.com/blog/200-miles-theepicbikeride']}
,
 {title:'One stroke.<br>Then the next.',description:'Patience in the water. Consistency on land.<br>The quieter side of an Ironman journey.',label:'04 / THE SWIM CHAPTER',role:'FIND YOUR RHYTHM. KEEP GOING.',nav:[['Ironman','#miles'],['Swim film','#endurance'],['My writing','#writing'],['OET community','#contact']],cta:['Explore my endurance story','#miles'],feature:['Watch my real swimming reel','https://www.instagram.com/yeswanth_kanumuri/reel/Co7c84SAAlp/']},
 {title:'Different terrain.<br>Same curiosity.',description:'A little adventure keeps the perspective fresh.<br>Explore, make, share. #OneEnergyTogether',label:'05 / THE EXPLORER',role:'MORE THAN A JOB TITLE. MORE THAN ONE TERRAIN.',nav:[['The person','#about'],['Photo journal','#journal'],['Field notes','#writing'],['Say hello','#contact']],cta:['Explore the personal side','#journal'],feature:['Stories from One Energy Together','#writing']}
 ];
 function paintWorld(){const w=worlds[mode];stage.dataset.world=String(mode);document.querySelector("#season-caption").textContent=PortfolioWeather.labels[mode];document.querySelector('#journey-title').innerHTML=w.title;document.querySelector('#journey-description').innerHTML=w.description;document.querySelector('#journey-eyebrow').textContent=w.label;document.querySelector('#world-role').textContent=w.role;const nav=document.querySelector('#world-nav');nav.replaceChildren(...w.nav.map(([name,href])=>{const a=document.createElement('a');a.textContent=name;a.href=href;return a}));const cta=document.querySelector('.journey-cta');cta.href=w.cta[1];cta.textContent=w.cta[0];const feature=document.querySelector('#world-feature');feature.href=w.feature[1];feature.querySelector('strong').textContent=w.feature[0];feature.target=w.feature[1].startsWith('http')?'_blank':'_self';feature.rel='noopener noreferrer';document.querySelectorAll('[data-activity]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.activity===mode)));}
 const pause=document.querySelector('.journey-pause');
 function change(m){if(mode===m||!Number.isFinite(m))return;previousMode=mode;mode=m;needsDraw=true;transition=reduced.matches?1:0;paintWorld();if(!reduced.matches)document.querySelector('.journey-copy').animate([{opacity:.25,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.2,.8,.2,1)'})}
 paintWorld();
 document.querySelectorAll('[data-activity]').forEach(b=>b.addEventListener('click',()=>{manualMode=true;change(+b.dataset.activity)}));
 function syncPause(){needsDraw=true;pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Play character animation':'Pause character animation');document.dispatchEvent(new CustomEvent('portfolio-motion',{detail:{paused}}))}syncPause();pause.addEventListener('click',()=>{paused=!paused;syncPause()});
 function scroll(){const r=section.getBoundingClientRect(),travel=section.offsetHeight-H;p=travel>1?Math.max(0,Math.min(1,-r.top/travel)):0;stage.style.setProperty('--journey-progress',p);if(r.bottom<0)manualMode=false;if(!manualMode&&!reduced.matches&&travel>1){const scene=Math.min(4,Math.floor(p*5));if(scene!==lastScrollScene){lastScrollScene=scene;change(scene)}}visible=r.bottom>0&&r.top<H}
 function resize(){needsDraw=true;W=stage.clientWidth;H=stage.clientHeight;const d=Math.min(devicePixelRatio,2);canvas.width=W*d;canvas.height=H*d;c.setTransform(d,0,0,d,0,0);bg.width=W*d;bg.height=H*d;bc.setTransform(d,0,0,d,0,0);scroll()}
 reduced.addEventListener('change',()=>{paused=reduced.matches;syncPause();resize()});addEventListener('resize',resize);addEventListener('scroll',scroll,{passive:true});resize();
 function path(points,color,width){c.beginPath();points.forEach((q,i)=>i?c.lineTo(...q):c.moveTo(...q));c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke()}
 function poly(points,color){c.beginPath();points.forEach((q,i)=>i?c.lineTo(...q):c.moveTo(...q));c.closePath();c.fillStyle=color;c.fill()}
 function ellipse(x,y,rx,ry,color){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=color;c.fill()}
 function ground(){return H*(W<700?.57:.8)}
 const cadence=[5.5,3.5,5,3.5,3.7];
 function actor(time,activity,alpha=1,offset=0){const img=sheets[activity];if(!img.complete||!img.naturalWidth)return;const mobile=W<700;const box=mobile?Math.min(W*.86,H*.39):Math.min(H*.52,W*.51);const frame=Math.floor(time*cadence[activity])%8;const phase=time*cadence[activity]/8*Math.PI*2;const cw=img.naturalWidth/4,ch=img.naturalHeight/2;let x=W*(mobile?.55:.68),y=ground();c.save();c.globalAlpha=alpha;if(activity!==3)ellipse(x,y+9,box*(activity===2?.35:.16),box*.019,'#63765028');const bob=activity===0?-Math.abs(Math.sin(phase*2))*box*.003:activity===1?-Math.abs(Math.sin(phase*2))*box*.0015:0;const glide=activity===3?Math.sin(phase)*box*.005:0;const lean=activity===4?Math.sin(phase)*.006:0;c.translate(x+offset+glide,y+bob);c.rotate(lean);const inset=activity===4&&frame===3?20:0;c.drawImage(img,(frame%4)*cw+inset,Math.floor(frame/4)*ch,cw-inset,ch,-box*.5+box*inset/cw,-box,box*(1-inset/cw),box);c.restore()}
 function draw(time){c.clearRect(0,0,W,H);bc.clearRect(0,0,W,H);const ease=1-Math.pow(1-transition,3);if(ease<1){bc.save();bc.globalAlpha=1-ease;PortfolioPlaces.draw(bc,time*.65,previousMode,W,H);bc.restore()}bc.save();bc.globalAlpha=ease;PortfolioPlaces.draw(bc,time*.65,mode,W,H);bc.restore();if(ease<1)actor(time,previousMode,1-ease,-35*ease);actor(time,mode,ease,35*(1-ease));if(mode===3){const b=W<700?Math.min(W*.86,H*.39):Math.min(H*.52,W*.51),surface=ground()-b*.49;c.save();c.globalAlpha=.3;const water=c.createLinearGradient(0,surface,0,H);water.addColorStop(0,'#8fc8d200');water.addColorStop(.15,'#8fc8d2');water.addColorStop(1,'#8fc8d2');c.fillStyle=water;c.fillRect(0,surface,W,H-surface);for(let j=0;j<3;j++){const pts=[];for(let x=0;x<W;x+=8)pts.push([x,surface+j*14+Math.sin(x/30+time*1.95+j)*3]);path(pts,'#f1fcfd',2)}c.restore()}if(ease<1)PortfolioWeather.draw(c,time*.65,previousMode,W,H,1-ease);PortfolioWeather.draw(c,time*.65,mode,W,H,ease)}
 let lastPaint=0;
 function render(now){const dt=Math.min((now-lastPaint)/1000,.06);if(visible&&!document.hidden&&(!paused||transition<1||needsDraw)&&now-lastPaint>=1000/30){needsDraw=false;lastPaint=now;if(!paused&&!document.hidden)t+=dt;transition=Math.min(1,transition+dt*2.2);draw(t)}requestAnimationFrame(render)}requestAnimationFrame(render);
 if(!reduced.matches){document.querySelector('.journey-name').animate([{opacity:0,transform:'translateY(35px)'},{opacity:1,transform:'translateY(0)'}],{duration:1000,easing:'cubic-bezier(.16,1,.3,1)'})}
})();
